#!/usr/bin/env python3
"""Publish task-runner tables and figures from a complete independently audited series."""
import argparse,hashlib,html,json,statistics,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
SYSTEMS=['nift','turbo','nx'];NAMES={'nift':'Nift','turbo':'Turbo','nx':'Nx'};COLORS={'nift':'#a3fb68','turbo':'#dbb585','nx':'#cf9bb8'}
LABELS={'noop':'Unchanged','leaf':'One leaf dirty','shared':'Generated prerequisite dirty','fanout':'10% inputs dirty','full':'All inputs dirty','one-percent':'1% inputs dirty','uncached-full':'Cache-disabled full','target-leaf':'Targeted leaf','target-subgraph':'Targeted release closure','multi-target':'Two targets'}
def esc(x):return html.escape(str(x))
def fmt(x):return f'{x:,.3f}'
def table(caption,heads,rows,prose=False):
 return '<div class="table-scroll" tabindex="0" role="region" aria-label="'+esc(caption)+'"><table class="'+('prose-table' if prose else '')+'"><caption>'+esc(caption)+'</caption><thead><tr>'+''.join('<th scope="col">'+esc(x)+'</th>' for x in heads)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">' if i==0 else '<td>')+esc(x)+('</th>' if i==0 else '</td>') for i,x in enumerate(r))+'</tr>' for r in rows)+'</tbody></table></div>'
def section(anchor,n,title,body):return f'<section class="report" id="{anchor}"><div class="section-head"><p class="eyebrow">{n} / {anchor}</p><h2>{title}</h2></div>{body}</section>'
def render(evidence,commit,series):
 assert len(commit)==40 and all(c in '0123456789abcdef' for c in commit)
 data=json.loads((evidence/'summary.json').read_text());assert data['all_correct']
 audit=json.loads((evidence.parent/'AUDIT.json').read_text());identity=json.loads((evidence/'identity.json').read_text());machine=json.loads((evidence.parent/'provenance/environment.json').read_text())
 assert audit['all_passed'] and audit['representative_same_node_three_way_passed']
 assert identity['candidate_sha']=='c14d06835bca515a5281e41da0e40219c2d60ef0' and identity['suite_sha']=='f37b63bd13cf71256607ba4652bcc911e270f94e' and not identity['suite_dirty']
 env={'suite_sha':identity['suite_sha'],'nift_sha':identity['candidate_sha'],'node':'Node 22.22.1','npm':'9.2.0','turbo_version':'2.11.7','compiler':machine['compiler'],'cpu_model':machine['cpu_model'],'kernel':machine['kernel'],'filesystem':'ext4; prepared local fixtures'}
 rows=[json.loads(x) for x in (evidence/'observations.jsonl').read_text().splitlines()]
 assert data['observations']==len(rows)==1527 and data['measured']==1434 and data['cells']==93
 cells=data['summary'];ix={(c['tiny'],c['size'],c['jobs'],c['case'],c['runner']):c for c in cells}
 for c in cells:
  sample=[r for r in rows if not r['warmup'] and all(r[k]==c[k] for k in ['tiny','size','jobs','case','runner'])]
  assert len(sample)==c['samples']
  for m in ['wall_ms','cpu_ms','peak_rss_kib']:assert statistics.median(r['metrics'][m] for r in sample)==c[m]['median']
 def cell(tiny,size,jobs,case,runner):return ix[tiny,size,jobs,case,runner]
 assets=ROOT/'public/benchmarks/task-runners/assets';assets.mkdir(parents=True,exist_ok=True)
 import matplotlib;matplotlib.use('Agg')
 import matplotlib.pyplot as plt
 plt.rcParams.update({'figure.facecolor':'#191e19','axes.facecolor':'#191e19','axes.edgecolor':'#697660','axes.labelcolor':'#e8ece3','text.color':'#e8ece3','xtick.color':'#adb6a6','ytick.color':'#adb6a6','grid.color':'#354132','font.family':'DejaVu Sans','font.size':11,'svg.fonttype':'none','svg.hashsalt':'nift-task-runners'})
 def chart(slug,title,tiny,sizes,case,metric='wall_ms',unit='ms',jobs=4,workers=False,log=False):
  fig,ax=plt.subplots(figsize=(11,3.7));fig.subplots_adjust(left=.12,right=.97,top=.82,bottom=.20)
  divisor=1024 if unit=='MiB' else 1000 if unit=='s' else 1
  values={s:[cell(tiny,100 if workers else n,n if workers else jobs,case,s)[metric]['median']/divisor for n in sizes] for s in SYSTEMS}
  for s in SYSTEMS:ax.plot(sizes,values[s],color=COLORS[s],marker={'nift':'o','turbo':'s','nx':'^'}[s],label=NAMES[s],lw=2,markersize={'nift':5,'turbo':7,'nx':9}[s],linestyle={'nift':'-','turbo':'--','nx':':'}[s],markerfacecolor='none',markeredgewidth=1.4,zorder={'nift':3,'turbo':2,'nx':1}[s])
  ax.set_xscale('log',base=2 if workers else 10);ax.set_xticks(sizes,labels=[f'{n:,}' for n in sizes]);ax.set_xlabel('Worker limit' if workers else 'Independent tiny tasks' if tiny else 'Mixed project tasks')
  ax.set_ylabel(('Maximum-child RSS' if metric=='peak_rss_kib' else 'Elapsed time')+' ('+unit+')'+(' · log scale' if log else ''))
  if log:ax.set_yscale('log')
  else:ax.set_ylim(bottom=0)
  ax.grid(True,alpha=.7);ax.legend(loc='lower left',bbox_to_anchor=(0,1.02),ncols=3,frameon=False);ax.spines[['top','right']].set_visible(False)
  for ext in ['svg','png']:fig.savefig(assets/(slug+'.'+ext),dpi=180,metadata={'Date':None} if ext=='svg' else {'Software':'Nift Labs task-runners'})
  svg=assets/(slug+'.svg');svg.write_text('\n'.join(line.rstrip() for line in svg.read_text().splitlines())+'\n')
  plt.close(fig)
  tabrows=[]
  for i,n in enumerate(sizes):
   cs=[cell(tiny,100 if workers else n,n if workers else jobs,case,s) for s in SYSTEMS]
   assert len(set(c['samples'] for c in cs))==1
   tabrows.append([f'{n:,}',*[fmt(values[s][i]) for s in SYSTEMS],cs[0]['samples']])
  scale=('Both axes logarithmic.' if log else 'Value axis starts at zero; task-count spacing is logarithmic.') if not workers else 'Value axis starts at zero; worker-count spacing is logarithmic.'
  prefix='public/benchmarks/task-runners/assets/'
  return '<figure class="visual"><div class="plot-scroll" tabindex="0" role="region" aria-label="'+esc(title)+' chart"><img src="@path(\''+prefix+slug+'.svg\')" alt="'+esc(title)+'; Nift, Turbo, Nx"></div><figcaption>'+esc(title)+'. '+scale+' Lines join measured points, not a fitted model. Same cohort, ordering, units and medians in chart and table. <a href="@path(\''+prefix+slug+'.svg\')">SVG</a> / <a href="@path(\''+prefix+slug+'.png\')">PNG</a></figcaption>'+table(title+f'; median {unit}; '+('100 mixed tasks' if workers else f'j{jobs}'),['Workers' if workers else 'Tasks',*[NAMES[s]+' '+unit for s in SYSTEMS],'n / cell'],tabrows)+'</figure>'
 def matrix(tiny,size,jobs,cases):
  out=[]
  for case in cases:
   cs=[cell(tiny,size,jobs,case,s) for s in SYSTEMS]
   out.append([LABELS[case],*[fmt(c['wall_ms']['median']) for c in cs],cs[0]['executed_tasks'],cs[0]['samples']])
  return table(f'{size:,} '+('tiny' if tiny else 'mixed')+f' tasks; j{jobs}; median ms',['Case',*[NAMES[s]+' ms' for s in SYSTEMS],'Executed','n / cell'],out)
 base=f'https://github.com/nift-experiments/lab-evidence/tree/{commit}/benchmarks/task-runners/{series}'
 suite=f'https://github.com/nift-experiments/task-runners/tree/{env["suite_sha"]}'
 console='''<div class="console"><div class="console-top"><span>WORKFLOW / 012 CORE TASKS</span><span class="state">CHECKED</span></div><div class="lanes"><div class="lane"><span>generate</span><div class="nodes"><span class="node">schema</span><span class="arrow">→</span><span class="node">client</span></div></div><div class="lane"><span>check</span><div class="nodes"><span class="node">types</span><span class="node">unit</span><span class="node">lint</span></div></div><div class="lane"><span>produce</span><div class="nodes"><span class="node">web</span><span class="node">helper</span><span class="node">docs</span></div></div><div class="lane"><span>release</span><div class="nodes"><span class="node">package</span><span class="arrow">→</span><span class="node">integration</span><span class="arrow">→</span><span class="node">verify</span><span class="arrow">→</span><span class="node">release</span></div></div></div><p>Branches converge on package. Client feeds docs; helper is independent. Added asset families exercise fan-out and independent lanes. <a href="#workflow">Exact relationships ↓</a></p></div>'''
 body='<main id="main"><div class="hero"><div><p class="eyebrow">Task runners / same-node experiment</p><h1>Work has<br><em>an order.</em></h1><p class="lede">Nift, Turbo and Nx run the same project workflow. What happens when tasks are clean, inputs change, branches run together—or a prerequisite fails?</p><p class="label">20 → 100 → 1,000 tasks / workers 1, 2, 4</p></div>'+console+'</div><div class="participants"><div class="participant nift"><strong>Nift 4.12.0 final</strong>Source-built snapshot. Programmable .f actions, tracked ordering and file invalidation.</div><div class="participant turbo"><strong>Turbo 2.11.7</strong>Package-script tasks, explicit pipeline and native local task cache.</div><div class="participant nx"><strong>Nx 23.3.0</strong>Project targets, run-commands executor and native local task cache.</div></div><div class="counts"><span><b>1,434</b> measured observations</span><span><b>93</b> runner cells</span><span><b>93</b> retained warmups</span><span><b>1</b> fresh shared-CPU node</span></div><nav class="jump" aria-label="Report sections">'+''.join(f'<a href="#{a}">{t}</a>' for a,t in [('workflow','The workflow'),('noop','Nothing changed'),('leaf','Partial work'),('fanout','Fan-out'),('full','All dirty'),('parallel','Parallel lanes'),('failure','Failure'),('tiny','Tiny tasks'),('inputs','Inputs & cache'),('resources','Resources'),('correctness','Correctness'),('practitioner','Practitioner view'),('method','Evidence')])+'</nav>'

 body+='<p class="note">At 1,000 mixed tasks / j4, unchanged CLI medians were '+', '.join(NAMES[r]+' '+fmt(cell(False,1000,4,'noop',r)['wall_ms']['median'])+' ms' for r in SYSTEMS)+'. All-dirty medians were '+', '.join(NAMES[r]+' '+fmt(cell(False,1000,4,'full',r)['wall_ms']['median']/1000)+' s' for r in SYSTEMS)+'. These are descriptive observations of this workflow; the full-dirty cells have three measured samples.</p>'
 body+=section('workflow','01','One workflow. Three native descriptions.','<p>The common quantitative graph uses identical Python task bodies: content-hashed JSON outputs, text transforms, checks, one real helper compilation/execution, deterministic in-memory packaging and release validation. Additional asset tasks expand the graph. Each successful check produces a receipt in all runners.</p><p>Task names model workflow roles. Checks assert known properties of a 32-record input; web/docs transform text; the helper compiles a trivial C program; package validates an in-memory tar. No real TypeScript compiler, application test suite, framework build or deployment is measured.</p><p class="note">Cached check receipts are not always-run, outputless checks. This is a synthetic single-project workflow—not a production JavaScript framework, package discovery benchmark, or remote-cache comparison. Outputless APIs are outside this refresh’s matched capability certification.</p>'+table('Core ordering; task inputs additionally declare consumed artifact bytes',['Task','Prerequisites'],[['generate-schema','none'],['generate-client','generate-schema'],['typecheck / unit-test','generate-client'],['lint / build-helper','none'],['build-web','typecheck, lint, unit-test'],['docs','generate-client'],['package','build-web, build-helper, docs'],['integration-test','package'],['verify','integration-test'],['release-prep','verify']],True))
 body+=section('noop','02','Nothing changed. State still costs time.','<p>Every task body must remain unexecuted. Nift checks retained tracked input/output state; Turbo and Nx report native local cache hits with output files already present. These are different skip mechanisms, measured as fresh CLI invocations over prepared state. Nx daemon and remote caching are disabled.</p>'+chart('mixed-noop','Unchanged mixed workflow',False,[20,100,1000],'noop',log=True))
 body+=section('leaf','03','One leaf changes. Selection stays explicit.','<p>Changing one independent asset executes exactly that task while the full graph remains in view. The targeted comparisons start with dirty selected tasks, so Nift’s force-target behavior does not add unneeded work. Release selection includes its prerequisite closure; an untimed full invocation subsequently refreshes unselected consumers.</p>'+chart('mixed-leaf','One dirty leaf',False,[20,100,1000],'leaf')+matrix(False,20,4,['target-leaf','target-subgraph','multi-target'])+'<p class="note">Nift named targets are forced rather than a clean “ensure” operation. The graph’s worker limit is configured in the project; the frozen adapter does not use per-invocation worker overrides; this is not an exhaustive current-API capability test.</p>')
 body+=section('fanout','04','A changed input reaches its consumers.','<p>The 10% case changes independent asset inputs. The generated-prerequisite case changes schema input and requires the complete transitive consumer set, including schema-dependent added assets. Ordering alone is insufficient: consumed output bytes are declared as invalidation inputs.</p>'+chart('mixed-fanout','10% task inputs dirty',False,[20,100,1000],'fanout')+chart('mixed-shared','Generated prerequisite dirty',False,[20,100,1000],'shared'))
 body+=section('full','05','All inputs dirty. Every task runs.','<p>Unique bytes change in every task input. Native caching remains enabled, including cache writes, but the exact execution oracle requires all tasks to run. These light controlled bodies do not estimate savings in compiler- or application-test-dominated projects. A separate 20-task cohort explicitly disables Turbo/Nx task-cache reads and writes and forces Nift work; these modes are not pooled.</p>'+chart('mixed-full','All mixed-task inputs dirty',False,[20,100,1000],'full',unit='s')+matrix(False,20,4,['uncached-full'])+table('Full-dirty throughput; task count / median wall seconds; j4',['Graph','Nift tasks/s','Turbo tasks/s','Nx tasks/s'],[[('tiny' if tiny else 'mixed')+' / '+str(n),*[fmt(n/(cell(tiny,n,4,'full',r)['wall_ms']['median']/1000)) for r in SYSTEMS]] for tiny,sizes in [(False,[20,100,1000]),(True,[100,1000])] for n in sizes]))
 body+=section('parallel','06','Independent branches share the worker budget.','<p>One hundred mixed tasks execute with limits of one, two and four. Task-body start/complete events independently verify ordering and overlap. These limits control task bodies; they do not imply an equal total operating-system process count because native launch layers differ.</p>'+chart('workers','Mixed workflow worker scaling',False,[1,2,4],'full',unit='s',workers=True)+table('Maximum observed task-body overlap, 100 mixed tasks, full dirty',['Worker limit',*map(NAMES.get,SYSTEMS)],[[j,*[cell(False,100,j,'full',s)['peak_body_concurrency'] for s in SYSTEMS]] for j in [1,2,4]]))
 body+=section('failure','07','A failure blocks descendants, not independent work.','<p>Semantic certification injects a schema failure, requires a nonzero exit, blocks its descendants and checks independent branch completion. Recovery verifies all expected work and output bytes. These feature tests are separate from successful timing distributions.</p>'+table('Observed failure and retry behavior',['Runner','Failure / recovery'],[['Nift','Names the failed custom action; independent branches complete. A normal retry reports unfinished build; build --repair is required.'],['Turbo','Failed npm task exits nonzero; dependencies-successful continuation permits independent work and blocks dependent tasks. Fix then rerun.'],['Nx','Target failure produces a failed-task summary and nonzero status. Independent targets complete; dependent targets do not run. Fix then rerun.']],True)+'<p>Actual stdout/stderr and start/complete/fail traces are retained with the semantic observations. Exit-code values differ and are not treated as a performance result. Turbo/Nx recovery is tested with full forced execution; Nift uses repair. These tests certify correct retry, not the fastest default incremental recovery path.</p>')
 body+=section('tiny','08','Tiny work exposes orchestration and launch cost.','<p>The same compiled C body hashes a small input and writes one deterministic output. Independent 100- and 1,000-task graphs exercise unchanged, one-task, 1%, 10% and full-dirty cases. Turbo retains its npm script launch layer, Nx uses run-commands, and Nift uses cmd: this is not isolated scheduler CPU.</p>'+chart('tiny-noop','Unchanged tiny-task graph',True,[100,1000],'noop',log=True)+chart('tiny-leaf','One dirty tiny task',True,[100,1000],'leaf')+chart('tiny-fanout','10% tiny-task inputs dirty',True,[100,1000],'fanout')+chart('tiny-full','Fully dirty tiny-task graph',True,[100,1000],'full',unit='s')+matrix(True,1000,4,['noop','leaf','one-percent','fanout','full'])+'<p class="note">The optional 10,000-task cohort was excluded after local feasibility because repeated launch-heavy runs were disproportionate to this bounded diagnostic. This is a runtime-budget decision, not evidence of a graph-size capability limit.</p>')
 body+=section('inputs','09','Inputs, outputs and cache are distinct contracts.','<p>The frozen adapter declares file inputs and artifact ownership separately from task completion order. Nift validates retained state; Turbo/Nx use their native local result caches. Incremental skipping is not restoring missing outputs. Remote caching and daemon-assisted execution are excluded.</p>'+table('Capability evidence boundaries',['Question','What this refresh establishes'],[['Artifact-producing DAG','All three execute equivalent input/output/order contracts; exact action and output oracles pass.'],['Outputless checks / environment inputs','Not recertified as a matched new capability comparison. Receipt-producing checks in this adapter must not be presented as proof of every current API limit.'],['Task-result restoration','Native peer cache hits and prepared outputs are audited; no new Nift result-restoration implementation is claimed.'],['Ordering vs invalidation','Completion prerequisites and declared consumed file bytes remain distinct facts.'],['Remote cache / project inference','Not measured; choose a tool for these requirements using its own capability contract.']],True)+'<p>Supplemental comparisons not recertified by this suite are excluded from current results.</p>')
 body+=section('resources','10','Resource figures keep their measurement boundary.','<p>Every observation retains C-supervised wall time, CPU time and Linux wait4 maximum-child RSS. RSS is a child high-water measure—not summed simultaneous memory across parallel task/Node/compiler processes. The same incremental workloads appear in timing and memory panels.</p>'+chart('mixed-noop-rss','Unchanged workflow memory',False,[20,100,1000],'noop','peak_rss_kib','MiB')+chart('mixed-leaf-rss','One dirty leaf memory',False,[20,100,1000],'leaf','peak_rss_kib','MiB')+chart('mixed-full-rss','All dirty workflow memory',False,[20,100,1000],'full','peak_rss_kib','MiB'))
 body+=section('correctness','11','A fast skipped task is a rejected result.','<p>All 1,527 accepted observations pass exact task-start/completion/output, prerequisite order, concurrency, rotation, raw-metric and distribution audits. Every warmup remains. A first attempt reused preflight caches and was rejected at the first changed leaf when Turbo restored a cached result rather than executing the required action. Its 153 observations and failed command are preserved separately; none enter these distributions. The accepted run starts at the first cell in a fresh exact suite checkout with empty fixture/project caches.</p><p>The independently certified 21 semantic observations check failure, blocked descendants, independent completion and recovery. Outputless/environment behavior is outside the matched performance matrix. The unchanged refresh runner recognizes the accepted Nx cache-disabled receipt; this is a full new run, not a continuation or pooled partial series.</p>')
 distributions=[]
 for c in cells:
  distributions.append([('tiny' if c['tiny'] else 'mixed')+f" / {c['size']:,} / j{c['jobs']} / {LABELS[c['case']]}",NAMES[c['runner']],c['samples'],fmt(c['wall_ms']['median']),fmt(c['wall_ms']['min'])+'–'+fmt(c['wall_ms']['max']),fmt(c['wall_ms']['p95']) if c['wall_ms']['p95'] is not None else '—',fmt(c['cpu_ms']['median']),fmt(c['peak_rss_kib']['median']/1024),c['executed_tasks']])
 flagged=sum((c['wall_ms']['max']-c['wall_ms']['min'])/c['wall_ms']['median']>.25 for c in cells)
 body+='<p class="note">'+str(flagged)+' of 93 cells have a min–max span greater than 25% of their median. This is a descriptive spread flag, not a confidence interval. Sparse three-sample cells do not support tail or significance claims.</p>'
 body+='<details><summary>All 93 cells: timing distributions, CPU, memory and executed counts</summary>'+table('All observations retained; p95 only n ≥ 20; interpolated percentiles',['Case','Runner','n','Median ms','Min–max ms','p95 ms','CPU ms','RSS MiB','Executed'],distributions)+'</details>'
 body+=section('practitioner','12','AI-DX changes the choice—but not the evidence.','<p class="label">Qualitative practitioner judgement / observed contracts kept separate</p><p><strong>For human-plus-agent and agent-primary bespoke authored workflows, I would choose Nift.</strong> The same applies to mixed website/assets/helpers/tasks projects owned by Nift. All 31 measured configurations have the lowest Nift wall and maximum-child RSS medians here; programmable .f policy and explicit ownership, ordering, invalidation and lifecycle also matter.</p><p>I would choose Turbo/Nx for specific task-result restoration, remote-cache/platform or framework/workspace integration requirements. Those are concrete needs, not an architectural reason to default away from Nift for new bespoke work. The timed adapter does not establish the absence of every alternative current API.</p>'+table('AI-DX evidence classes',['Evidence','Conclusion'],[['Demonstrated','Exact actions, output bytes, completion order, bounded overlap, targeting and failure/recovery checks pass.'],['Source / representation','Separate artifact/input/order declarations make semantic roles inspectable.'],['Qualitative inference','That explicit structure can help agents make bounded, reviewable edits; helpers should remove duplicated boilerplate without collapsing semantics.'],['Not measured','Autonomous authoring success, repair rate, token/time cost, arbitrary-edit safety or a complete product-native structured error contract.']],True)+'<p>No numeric productivity or safety score is assigned. Harness JSON is not product-native structured feedback. Missing comparative probes do not establish competitor incapability.</p>')
 body+=section('method','13','Frozen sources. Retained samples. One node.',f'<p>One fresh 4-logical-CPU / 8-GB Ubuntu 24.04 Linode, us-east. CPU affinity includes all four CPUs. Runner order rotates within rounds; scenario order follows a fixed frozen plan. Fresh CLI invocation, prepared local state, no remote cache, Nx daemon disabled. Setup/input mutations are outside the timer; native dispatch, task work and bookkeeping are inside. Stdout/stderr are captured: native status formatting and cache-log costs are included; terminal painting is excluded. Turbo uses errors-only task logs and Nx uses static output. These CLI modes are retained with each command, not presented as equal pure scheduler CPU. No outlier removal.</p><p>The mixed body reads the canonical graph for each invocation; that identical cost is included. The suite covers 20/100/1,000 mixed tasks, 100/1,000 tiny tasks, j4 scaling, 100-task j1/j2 full-dirty work and 20-task cache-disabled/targeting cohorts. Failure and unsupported semantics are separate capability tests. Shared-CPU variance, sparse expensive cells and this synthetic single-project model limit generalization.</p><dl><dt>Nift source</dt><dd><code>{esc(env["nift_sha"])}</code></dd><dt>Measured suite</dt><dd><a href="{suite}"><code>{esc(env["suite_sha"])}</code></a></dd><dt>Toolchain</dt><dd>{esc(env["node"])} / npm {esc(env["npm"])} / Turbo {esc(env["turbo_version"])} / Nx 23.3.0 / {esc(env["compiler"])}</dd><dt>Machine</dt><dd>{esc(env["cpu_model"])} / {esc(env["kernel"])} / {esc(env["filesystem"])}</dd><dt>Canonical evidence</dt><dd><a href="{base}">Raw samples, traces, provenance, semantic probes, audit and lifecycle</a></dd><dt>Core follow-up</dt><dd><a href="{base}/AUDIT.json">Reproducible semantic/DX gaps</a>; Nift core was not changed.</dd><dt>Reproduce</dt><dd><a href="{suite}/docs/METHODOLOGY.md">Fairness contract</a> · <a href="{suite}/docs/official-plan.json">Sample plan</a> · <a href="{suite}/scripts/audit.py">Independent auditor</a></dd></dl>')
 commands=[NAMES[r]+': '+' '.join(next(x['command'] for x in rows if x['runner']==r and x['size']==20 and not x['tiny'] and x['case']=='noop')) for r in SYSTEMS]
 body+='<details><summary>Actual invocations and reusable Nift action</summary><p>Representative 20-task unchanged command; worker count four. Nx daemon/cloud disabled; remote cache disabled. Each observation retains its complete invocation.</p><pre tabindex="0" role="region" aria-label="Measured task commands"><code>'+esc('\n'.join(commands))+'</code></pre><p>The Nift tracked graph uses one reusable supported .f hook:</p><pre tabindex="0" role="region" aria-label="Reusable Nift action"><code>'+esc('r := cmd("python3", "task_body.py", getenv("NIFT_HOOK_TARGET")).cwd(getenv("NIFT_HOOK_ROOT")).run()\nif(!r.launched || r.exit_code != 0) { throw error(r.stderr, "user.task.failed") }')+'</code></pre><p>Direct lint/test/package/release .f examples are separately certified over prepared prerequisites; they do not implement an adapter scheduler.</p></details>'
 body+='</main>'
 dest=ROOT/'content/benchmarks/task-runners';dest.mkdir(parents=True,exist_ok=True);(dest/'index.html').write_text(body+'\n')
 compact={'series':series,'evidence_commit':commit,'summary_sha256':hashlib.sha256((evidence/'summary.json').read_bytes()).hexdigest(),'suite_sha':env['suite_sha'],'nift_sha':env['nift_sha'],'observations':data['observations'],'measured':data['measured'],'cells':cells};(dest/'published.json').write_text(json.dumps(compact,separators=(',',':'))+'\n')
 print('Rendered 93 runner cells from 1,527 audited observations')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--evidence',type=Path,required=True);p.add_argument('--commit',required=True);p.add_argument('--series',required=True);a=p.parse_args();render(a.evidence,a.commit,a.series)
